#!/bin/bash
# Mirror for lightweightbot: this server (the mirror) forwards the vpnbot
# server's open ports to it with socat, one systemd service per port, so
# the forwarding survives logout and reboot.
#   to the server over IPv4:  sudo bash socat.sh
#   over IPv6:                sudo bash socat.sh <server IPv6 address>
#   remove:                   sudo bash socat.sh remove
# Generated by the bot: the server address and the ports open on it.
set -u

TARGET="~ip~"
TCP_PORTS="~tcp~"
UDP_PORTS="~udp~"
NAME=vpnbot-mirror
UNIT_DIR=${UNIT_DIR:-/etc/systemd/system}

die() { echo "error: $*" >&2; exit 1; }

[ "$(id -u)" = 0 ] || die "run as root (sudo bash $0)"
command -v systemctl > /dev/null || die "systemd is required"

remove() {
    for f in "$UNIT_DIR/$NAME"-*.service; do
        [ -e "$f" ] || continue
        systemctl disable --now "$(basename "$f")" > /dev/null 2>&1
        rm -f "$f"
    done
    systemctl daemon-reload
}

if [ "${1:-}" = remove ]; then
    remove
    echo "mirror removed"
    exit 0
fi

# clients connect to this server over IPv4; the forwarding to the vpnbot
# server goes over IPv4 (the address below) or IPv6 (given as argument)
FAMILY=4
DEST=$TARGET
if [ -n "${1:-}" ]; then
    [[ "$1" =~ ^[0-9A-Fa-f:]+$ && "$1" == *:* ]] || die "not an IPv6 address: $1"
    FAMILY=6
    TARGET=$1
    DEST="[$1]"
fi

if ! command -v socat > /dev/null; then
    echo "installing socat..."
    if command -v apt-get > /dev/null; then
        apt-get update -q && apt-get install -y -q socat
    elif command -v dnf > /dev/null; then
        dnf install -y socat
    elif command -v yum > /dev/null; then
        yum install -y socat
    fi
    command -v socat > /dev/null || die "install socat and run again"
fi
SOCAT=$(command -v socat)

# the server must answer on 443 at the chosen address before anything is set up
timeout 5 bash -c "exec 3<>/dev/tcp/$TARGET/443" 2> /dev/null \
    || die "the server does not answer at $TARGET port 443 (IPv$FAMILY)"

# services of an earlier run go first, so their ports count as free
remove

# a port is taken when something else listens on it on a non-loopback
# address (127.0.0.53:53 of systemd-resolved does not count)
taken() {
    ss -H -ln"$1" "sport = :$2" | awk '{print $4}' | grep -vqE '^(127\.|\[::1\]|::1)'
}
for p in $TCP_PORTS; do
    taken t "$p" && die "port $p/tcp is taken: $(ss -H -lntp "sport = :$p" | head -1)"
done
for p in $UDP_PORTS; do
    taken u "$p" && die "port $p/udp is taken: $(ss -H -lnup "sport = :$p" | head -1)"
done

unit() {
    local proto=$1 port=$2 up
    up=${proto^^}
    cat > "$UNIT_DIR/$NAME-$proto-$port.service" <<UNIT
[Unit]
Description=vpnbot mirror $port/$proto -> $TARGET
Wants=network-online.target
After=network-online.target

[Service]
ExecStart=$SOCAT ${up}4-LISTEN:$port,fork,reuseaddr $up$FAMILY:$DEST:$port
Restart=always
RestartSec=3
DynamicUser=yes
AmbientCapabilities=CAP_NET_BIND_SERVICE
CapabilityBoundingSet=CAP_NET_BIND_SERVICE
NoNewPrivileges=yes

[Install]
WantedBy=multi-user.target
UNIT
}
for p in $TCP_PORTS; do unit tcp "$p"; done
for p in $UDP_PORTS; do unit udp "$p"; done
systemctl daemon-reload

failed=0
for f in "$UNIT_DIR/$NAME"-*.service; do
    u=$(basename "$f")
    if systemctl enable --now "$u" > /dev/null 2>&1 && sleep 2 && systemctl is-active -q "$u"; then
        echo "ok      ${u#"$NAME"-}"
    else
        echo "FAILED  ${u#"$NAME"-} (journalctl -u $u)"
        failed=1
    fi
done

echo
echo "forwarding to $TARGET (IPv$FAMILY): tcp $TCP_PORTS${UDP_PORTS:+, udp $UDP_PORTS}"
echo "in the bot, add this mirror's IP to Settings -> IP ban -> ignorelist"
echo "remove: sudo bash $0 remove"
exit $failed
